import java.util.PriorityQueue

data class Task(val name: String, val priority: Int, val seq: Long)

private val counter = java.util.concurrent.atomic.AtomicLong()
val pq = PriorityQueue<Task>(compareBy<Task> { it.priority }.thenBy { it.seq })  // seq: FIFO among equals

pq += Task("write", 5, counter.incrementAndGet())      // Kotlin's plusAssign on a MutableCollection
val next: Task? = pq.poll()

